original.query:
PREFIX wd:       <http://www.wikidata.org/entity/>
PREFIX wdt:      <http://www.wikidata.org/prop/direct/>
PREFIX apsearch: <https://linkedmusic.ca/graphs/ckg-apsearch/>
SELECT DISTINCT ?work ?date
WHERE {
  GRAPH apsearch: {
    ?work a apsearch:Work ;
          wdt:P123 ?publisher ;
          wdt:P571 ?date .
    ?publisher wdt:P2888 wd:Q219989 .
  }
  FILTER(STR(?date) >= "1900" && STR(?date) < "2025")
}
ORDER BY ?date
LIMIT 100

original_first100_types.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX apsearch: <https://linkedmusic.ca/graphs/ckg-apsearch/>
SELECT ?type (COUNT(DISTINCT ?work) AS ?works) WHERE {
{ SELECT DISTINCT ?work ?date WHERE { GRAPH apsearch: {
?work a apsearch:Work ; wdt:P123 ?publisher ; wdt:P571 ?date .
?publisher wdt:P2888 wd:Q219989 . }
FILTER(STR(?date) >= "1900" && STR(?date) < "2025") }
ORDER BY ?date LIMIT 100 }
GRAPH apsearch: { ?work wdt:P31 ?type } } GROUP BY ?type

publisher_media_dates.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX apsearch: <https://linkedmusic.ca/graphs/ckg-apsearch/>
SELECT ?publisher ?publisherQid ?type
(COUNT(DISTINCT ?work) AS ?works) (COUNT(DISTINCT ?datedWork) AS ?datedWorks)
(MIN(STR(?date)) AS ?earliest) (MAX(STR(?date)) AS ?latest)
WHERE { GRAPH apsearch: {
?work a apsearch:Work ; wdt:P123 ?publisher ; wdt:P31 ?type .
OPTIONAL { ?publisher wdt:P2888 ?publisherQid }
OPTIONAL { ?work wdt:P571 ?date . BIND(?work AS ?datedWork) }
} } GROUP BY ?publisher ?publisherQid ?type ORDER BY DESC(?works)

early_samples.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX apsearch: <https://linkedmusic.ca/graphs/ckg-apsearch/>
SELECT ?work ?label ?date ?type ?url ?classifier WHERE {
GRAPH apsearch: { ?work a apsearch:Work ; rdfs:label ?label ; wdt:P571 ?date ; wdt:P31 ?type .
OPTIONAL { ?work wdt:P953 ?url }
OPTIONAL { ?work <https://nfdi4culture.de/ontology/CTO_0001026> ?classifier }
FILTER(STR(?date) < "1950") } } ORDER BY ?date ?work LIMIT 8

